#!/usr/bin/env python3import sysfrom pathlib import Pathtarget = Path("bin/agent/prompts.py")raw = target.read_bytes()sys.stdout.write(f"File size: {len(raw)}\n")sys.stdout.write(f"Has CRLF: {b'\\r\\n' in raw}\n")sys.stdout.flush()src = raw.decode("utf-8")src_norm = src.replace("\r\n", "\n")# Check anchorssys.stdout.write(f"_prompt_node found: {'def _prompt_node' in src_norm}\n")sys.stdout.write(f"return prompt found: {'    return prompt\\n' in src_norm}\n")sys.stdout.write(f"read_prompts_config found: {'def read_prompts_config(' in src_norm}\n")sys.stdout.write(f"--reset-system found: {'--reset-system' in src_norm}\n")sys.stdout.flush()# Show context around _prompt_nodeidx = src_norm.find("def _prompt_node")if idx >= 0:    snippet = src_norm[idx:idx+300]    sys.stdout.write(f"Context: {repr(snippet[:200])}\n")    sys.stdout.flush()